  3	declare(strict_types=1);
  4	
  5	namespace testsuites\Application\Admin\Wizard;
  6	
  7	use Application\Admin\Wizard\InvalidationHandler;
  8	use Application\Admin\Wizard\WizardConfigurator;
  9	use Application\Admin\Wizard\WizardPreselection;
 10	use Application\AppFactory;
 11	use AppFrameworkTestClasses\ApplicationTestCase;
 12	
 13	/**
 14	 * Unit tests for {@see WizardConfigurator}.
 15	 *
 16	 * These tests cover session creation, preselection write-through to step data
 17	 * slots, accessor correctness, idempotency of {@see WizardConfigurator::getRedirectURL()},
 18	 * and custom setting-prefix key formatting.
 19	 */
 20	final class WizardConfiguratorTest extends ApplicationTestCase
 21	{
 22	    private const WIZARD_BASE_URL = 'https://example.com/admin/?page=wizardtest&mode=wizard';
 23	
 24	    // -------------------------------------------------------------------------
 25	    // test_createSessionWithPreselection
 26	    // -------------------------------------------------------------------------
 27	
 28	    /**
 29	     * getRedirectURL() must create a session and return a URL that contains
 30	     * the "wizard" query parameter with the session ID.
 31	     *
 32	     * Covers AC #1 and #3 from WP-003.
 33	     */
 34	    public function test_createSessionWithPreselection() : void
 35	    {
 36	        $configurator = new WizardConfigurator(self::WIZARD_BASE_URL);
 37	        $configurator->getPreselection()->setStepValue('Countries', 'country_id', 42);
 38	
 39	        $url = $configurator->getRedirectURL();
 40	
 41	        $this->assertStringContainsString('wizard=', $url);
 42	        $this->assertStringStartsWith(self::WIZARD_BASE_URL, $url);
 43	
 44	        // Extract the session ID from the URL and verify the session was created.
 45	        parse_str((string)parse_url($url, PHP_URL_QUERY), $params);
 46	        $sessionID = (string)($params['wizard'] ?? '');
 47	
 48	        $this->assertNotEmpty($sessionID, 'Session ID must not be empty in the redirect URL.');
 49	
 50	        $session = AppFactory::createSession();
 51	        $sessionData = $session->getValue($sessionID);
 52	
 53	        $this->assertIsArray($sessionData, 'Session data must be an array after getRedirectURL().');
 54	        $this->assertArrayHasKey('sessionID', $sessionData, 'Session data must contain the sessionID key.');
 55	        $this->assertSame($sessionID, $sessionData['sessionID']);
 56	    }
 57	
 58	    // -------------------------------------------------------------------------
 59	    // test_preselectionWrittenToStepSlots
 60	    // -------------------------------------------------------------------------
 61	
 62	    /**
 63	     * Preselection values must be written into the session under the step data
 64	     * key format: settingPrefix + '-step_' + stepName.
 65	     *
 66	     * For the default empty prefix this is '-step_Countries', '-step_Ticket', etc.
 67	     *
 68	     * Covers AC #3 from WP-003.
 69	     */
 70	    public function test_preselectionWrittenToStepSlots() : void
 71	    {
 72	        $configurator = new WizardConfigurator(self::WIZARD_BASE_URL);
 73	        $configurator->getPreselection()
 74	            ->setStepValue('Countries', 'country_id', 99)
 75	            ->setStepValue('Ticket', 'ticket_title', 'Hello World');
 76	
 77	        $url = $configurator->getRedirectURL();
 78	
 79	        parse_str((string)parse_url($url, PHP_URL_QUERY), $params);
 80	        $sessionID = (string)($params['wizard'] ?? '');
 81	
 82	        $session = AppFactory::createSession();
 83	        $sessionData = $session->getValue($sessionID);
 84	
 85	        // Default prefix '' produces keys '-step_Countries' and '-step_Ticket'.
 86	        $this->assertArrayHasKey('-step_Countries', $sessionData);
 87	        $this->assertSame(array('country_id' => 99), $sessionData['-step_Countries']);
 88	
 89	        $this->assertArrayHasKey('-step_Ticket', $sessionData);
 90	        $this->assertSame(array('ticket_title' => 'Hello World'), $sessionData['-step_Ticket']);
 91	
 92	        // The invalidationHandler key must also be present.
 93	        $this->assertArrayHasKey('-invalidationHandler', $sessionData);
 94	        $this->assertInstanceOf(InvalidationHandler::class, $sessionData['-invalidationHandler']);
 95	        $this->assertFalse($sessionData['-invalidationHandler']->isInvalidated());
 96	    }
 97	
 98	    // -------------------------------------------------------------------------
 99	    // test_getPreselectionReturnsInstance
100	    // -------------------------------------------------------------------------

101	        if ($this->sessionID === null)
102	        {
103	            $this->sessionID = $this->createSession();
104	        }
105	
106	        $separator = strpos($this->wizardBaseURL, '?') !== false ? '&' : '?';
107	
108	        return $this->wizardBaseURL . $separator . 'wizard=' . $this->sessionID;
109	    }
110	
111	    /**
112	     * Creates a new wizard session, initialises the invalidation handler key,
113	     * and writes all preselection values into the session step data slots using
114	     * the key format the wizard trait already reads:
115	     * `settingPrefix + '-step_' + stepName`.
116	     *
117	     * @return string The newly created session ID.
118	     */
119	    private function createSession() : string
120	    {
121	        $sessionID = BaseWizardMode::generateNewSessionID();
122	
123	        $session = AppFactory::createSession();
124	        $data = $session->getValue($sessionID);
125	
126	        $invalidationHandler = new InvalidationHandler();
127	        $invalidationHandler->setIsInvalidated(false);
128	
129	        $data[$this->settingPrefix . '-invalidationHandler'] = $invalidationHandler;
130	
131	        foreach ($this->preselection->getStepNames() as $stepName)
132	        {
133	            $key = $this->settingPrefix . '-step_' . $stepName;
134	            $data[$key] = $this->preselection->getStepValues($stepName);
135	        }
136	
137	        $session->setValue($sessionID, $data);
138	
139	        return $sessionID;
140	    }
141	}

101	
102	    /**
103	     * getPreselection() must return a WizardPreselection instance, and the same
104	     * instance must be returned on subsequent calls (identity).
105	     *
106	     * Covers AC #1 from WP-003.
107	     */
108	    public function test_getPreselectionReturnsInstance() : void
109	    {
110	        $configurator = new WizardConfigurator(self::WIZARD_BASE_URL);
111	
112	        $preselection = $configurator->getPreselection();
113	
114	        $this->assertInstanceOf(WizardPreselection::class, $preselection);
115	
116	        // Must return the same instance on repeated calls.
117	        $this->assertSame($preselection, $configurator->getPreselection());
118	    }
119	
120	    // -------------------------------------------------------------------------
121	    // test_customSettingPrefix
122	    // -------------------------------------------------------------------------
123	
124	    /**
125	     * When a non-empty settingPrefix is supplied, step data keys must be
126	     * prefixed accordingly: prefix + '-step_' + stepName.
127	     *
128	     * Covers AC #7 from WP-003 and future-proofing for wizards that call
129	     * setSettingPrefix().
130	     */
131	    public function test_customSettingPrefix() : void
132	    {
133	        $prefix = 'mywiz';
134	        $configurator = new WizardConfigurator(self::WIZARD_BASE_URL, $prefix);
135	        $configurator->getPreselection()->setStepValue('StepA', 'key1', 'val1');
136	
137	        $url = $configurator->getRedirectURL();
138	
139	        parse_str((string)parse_url($url, PHP_URL_QUERY), $params);
140	        $sessionID = (string)($params['wizard'] ?? '');
141	
142	        $session = AppFactory::createSession();
143	        $sessionData = $session->getValue($sessionID);
144	
145	        $expectedStepKey = $prefix . '-step_StepA';
146	        $expectedHandlerKey = $prefix . '-invalidationHandler';
147	
148	        $this->assertArrayHasKey($expectedStepKey, $sessionData, 'Step key must use the custom prefix.');
149	        $this->assertSame(array('key1' => 'val1'), $sessionData[$expectedStepKey]);
150	
151	        $this->assertArrayHasKey($expectedHandlerKey, $sessionData, 'InvalidationHandler key must use the custom prefix.');
152	
153	        // Keys with the default prefix must NOT be present.
154	        $this->assertArrayNotHasKey('-step_StepA', $sessionData, 'Default-prefix key must not exist when a custom prefix is used.');
155	    }
156	
157	    // -------------------------------------------------------------------------
158	    // test_getRedirectURLIsIdempotent
159	    // -------------------------------------------------------------------------
160	
161	    /**
162	     * Calling getRedirectURL() multiple times must return the same URL and
163	     * reuse the same session (idempotent after first call).
164	     *
165	     * Covers AC #8 from WP-003.
166	     */
167	    public function test_getRedirectURLIsIdempotent() : void
168	    {
169	        $configurator = new WizardConfigurator(self::WIZARD_BASE_URL);
170	        $configurator->getPreselection()->setStepValue('Countries', 'country_id', 1);
171	
172	        $url1 = $configurator->getRedirectURL();
173	        $url2 = $configurator->getRedirectURL();
174	
175	        $this->assertSame($url1, $url2, 'getRedirectURL() must return the same URL on repeated calls.');
176	    }
177	}

